powerpagecomponent.content:
{
  "source": "

{% assign compliancetypeid = '' %}
{% if request.params['registrationid'] %}
{% assign registrationid = request.params['registrationid'] %}
{% assign registration = entities['new_candidateregistration'][registrationid] %}
{% assign compliancetypeid = registration.new_compliancetypeid.id %}
{% assign managingaccountid = registration.new_managingaccountid.id %}

{% fetchxml compliancesettings %}
<fetch version="1.0" output-format="xml-platform" mapping="logical" distinct="false">
    <entity name="new_compliancesettings">
        <attribute name="new_compliancesettingsid" />
        <attribute name="new_name" />
        <attribute name="new_visible" />
        <attribute name="new_logicalname" />
        <attribute name="new_isrequired" />
        <attribute name="new_condition" />
        <filter type="and">
            <condition attribute="new_compliancetypeid" operator="eq" uitype="new_compliancetype"
                value="{{compliancetypeid}}" />
            <condition attribute="new_managingaccountid" operator="eq" uitype="account" value="{{managingaccountid}}" />
        </filter>
    </entity>
</fetch>
{% endfetchxml %}

<div id="complianceData" style="display: none;" data-settings='[
{% for item in compliancesettings.results.entities %}
  {
    "new_logicalname": "{{ item.new_logicalname | escape | json }}",
    "field_label": "{{ item.new_name | escape | json }}",
    "new_visible": {{ item.new_visible | json }},
    "new_isrequired": {{ item.new_isrequired | default: false | json }},
    "new_condition": {% if item.new_condition %}
    {
        "attribute": "{{ item.new_condition | replace: '<condition attribute=', '' | replace: '/>', '' | split: ' operator=' | first | replace: '\"', '' | trim }}",
        "operator": "{{ item.new_condition | replace: '<condition attribute=', '' | replace: '/>', '' | split: ' operator=' | last | split: ' value=' | first | replace: '\"', '' | trim }}",
        "value": "{% if item.new_condition contains 'value=' %}\"{{ item.new_condition | split: 'value=' | last | replace: '\"', '' | replace: '/>', '' | trim }}\"{% else %}true{% endif %}"
      }{% else %}false{% endif %}
  }{% unless forloop.last %},{% endunless %}
{% endfor %}
]'>
</div>

{% endif %}

<script type="text/javascript">
    $(document).ready(function () {
    var jsonSettings = $('#complianceData').attr('data-settings');
    console.log("JSON Data:", jsonSettings);  // Check what the JSON data actually looks like

    try {
        var complianceSettings = JSON.parse(jsonSettings);
        console.log("Parsed JSON:", complianceSettings);

        complianceSettings.forEach(function (setting) {
            console.log("Applying initial setting for:", setting.new_logicalname);
            applySetting(setting);

            if (setting.new_condition) {
                console.log("Adding listener for:", setting.new_logicalname);
                addFieldListener(setting);
            }
        });
    } catch (e) {
        console.error("Error parsing JSON:", e);
    }

    // this code is for proof of address page, Note to Lana "Don't Touch Please" till the end of updatePOAChecks function and the observer
    var checkExist = setInterval(function () {
        if ($('#new_numberofpoadocuments').length) {
            console.log("#new_numberofpoadocuments is now present.");
            clearInterval(checkExist);
            initPOACheck();
        }
    }, 100); // check every 100ms

    function initPOACheck() {
        var numPOADocumentsValue = $('#new_numberofpoadocuments').val();
        console.log('Retrieved numPOADocumentsValue:', numPOADocumentsValue);

        var requiredPOADocuments = parseInt(numPOADocumentsValue, 10);
        console.log('Parsed requiredPOADocuments:', requiredPOADocuments);

        if (isNaN(requiredPOADocuments)) {
            console.error('Invalid number of POA documents:', numPOADocumentsValue);
            requiredPOADocuments = 0; // Default or error handling
        }

        function updatePOAChecks() {
            var actualPOADocuments = $('#poadocs tr[data-entity]').length;
            console.log('Actual POA Documents:', actualPOADocuments);

            if (actualPOADocuments >= requiredPOADocuments) {
                $('#new_poacheckscomplete').prop('disabled', true);
            } else {
                $('#new_poacheckscomplete').prop('disabled', false);
            }
        }

        $('#new_numberofpoadocuments').change(updatePOAChecks);
        updatePOAChecks(); // Initial check on document ready

        // MutationObserver for dynamic changes in POA table
        var observer = new MutationObserver(function (mutations) {
            mutations.forEach(function (mutation) {
                if (mutation.type === 'childList') {
                    updatePOAChecks(); // Update the field state if rows are added or removed
                }
            });
        });

        var config = { childList: true, subtree: true };
        var targetNode = document.getElementById('poadocs');
        if (targetNode) {
            observer.observe(targetNode, config);
        }
    }

    try {
        var complianceSettings = JSON.parse(jsonSettings);
        console.log("Parsed JSON:", complianceSettings);

        complianceSettings.forEach(function (setting) {
            console.log("Applying initial setting for:", setting.new_logicalname);
            applySetting(setting);

            if (setting.new_condition) {
                console.log("Adding listener for:", setting.new_logicalname);
                addFieldListener(setting);
            }
        });
    } catch (e) {
        console.error("Error parsing JSON:", e);
    }
});

 function applySetting(setting) {
        var fieldName = setting.new_logicalname;
        var field = $('[id="' + fieldName + '"]');
        console.log("Field Name:", fieldName, "Field Found:", field.length > 0);

        if (field.length) {
            if (!setting.new_visible) {
                console.log("Hiding field:", fieldName);
                hideField(fieldName);
            } else {
                console.log("Showing field:", fieldName);
                showField(fieldName);
                if (setting.new_isrequired) {
                    console.log("Setting field as required:", fieldName);
                    var label = $('label[for="' + fieldName + '"]').text();
                    SetFieldAsRequired(fieldName, label);
                } else {
                    console.log("Setting field as non-required:", fieldName);
                    SetFieldAsNonRequired(fieldName);
                }
            }
        }
    }

function addFieldListener(setting) {
    var condition = setting.new_condition;
    var targetField = $('[id="' + condition.attribute + '"]');
    console.log("Adding listener to:", condition.attribute, "Field found:", targetField.length > 0);

    targetField.on('change', function () {
        console.log("Change detected on:", condition.attribute);
        evaluateConditionAndApply(setting);
    });

    // Initial evaluation to ensure the setting is applied based on the current field value.
    evaluateConditionAndApply(setting);
}

function evaluateConditionAndApply(setting) {
    var condition = setting.new_condition;
    var targetField = $('[id="' + condition.attribute + '"]');
    var value = targetField.val().trim(); // Trimming value
    var operator = condition.operator.trim(); 
    var conditionValue = condition.value.replace(/"/g, '').trim(); // Trimming condition value

    console.log("Evaluating condition for:", setting.new_logicalname);
    console.log("Target field value:", value, "Operator:", operator, "Condition value:", conditionValue);

    var conditionMet = false;

    switch (operator) {
        case 'eq':
            conditionMet = (value === conditionValue);
            break;
        case 'neq':
            conditionMet = (value !== conditionValue);
            break;
        case 'not-null':
            conditionMet = (value !== null && value !== "");
            break;
        // Add more cases as needed
        default:
            console.error("Unsupported operator:", operator);
    }

    if (conditionMet) {
        console.log("Condition met for:", setting.new_logicalname);
        toggleSetting(setting);
    } else {
        console.log("Condition not met for:", setting.new_logicalname);
        // Reapply the original setting if the condition is not met
        applySetting(setting);
    }
}

function toggleSetting(setting) {
        var fieldName = setting.new_logicalname;
        var field = $('[id="' + fieldName + '"]');
        console.log("Toggling field:", fieldName, "Field Found:", field.length > 0);

        if (field.length) {
            // Toggle visibility
            if (!setting.new_visible) {
                console.log("Field is hidden, showing it:", fieldName);
                showField(fieldName);
                setting.new_visible = true;
            } else {
                console.log("Field is visible, hiding it:", fieldName);
                hideField(fieldName);
                setting.new_visible = false;
            }

            // Toggle required status
            if (setting.new_isrequired) {
                console.log("Field is required, making it non-required:", fieldName);
                SetFieldAsNonRequired(fieldName);
                setting.new_isrequired = false;
            } else {
                console.log("Field is non-required, making it required:", fieldName);
                var label = $('label[for="' + fieldName + '"]').text();
                SetFieldAsRequired(fieldName, label);
                setting.new_isrequired = true;
            }
        }
    }
    function hideField(fieldName) {
        var field = document.getElementById(fieldName);
        if (field) {
            var parentTR = field.closest('td');
            if (parentTR) {
                parentTR.style.display = 'none';
            }
        }
    }

    function showField(fieldName) {
        var field = document.getElementById(fieldName);
        if (field) {
            var parentTR = field.closest('td');
            if (parentTR) {
                parentTR.style.display = '';
            }
        }
    }

    function SetFieldAsRequired(fieldName, displayname) {
        if (typeof (Page_Validators) == 'undefined') return;
        if ($("#" + fieldName) != undefined && $("#" + fieldName + "_label") != undefined) {
            $("#" + fieldName).prop('required', true);
            $("#" + fieldName).closest(".control").prev().addClass("required");
            // Create new validator object
            var Requiredvalidator = document.createElement('span');
            Requiredvalidator.style.display = "none";
            Requiredvalidator.id = fieldName + "Validator";
            Requiredvalidator.controltovalidate = fieldName;
            var errormessage = "<a href='#" + fieldName + "_label'>" + displayname + " is a required field.</a>";

            Requiredvalidator.errormessage = errormessage;
            Requiredvalidator.initialvalue = "";
            Requiredvalidator.evaluationfunction = function () {
                var fieldControl = $("#" + fieldName);
                if (fieldControl.is("span")) {
                    var value0 = $("#" + fieldName + "_0").prop("checked");
                    var value1 = $("#" + fieldName + "_1").prop("checked");
                    if (value0 == false && value1 == false) {
                        return false;
                    }
                    else {
                        return true;
                    }
                }
                else {
                    var value = $("#" + fieldName).val();
                    if (value == null || value == "") {
                        return false;
                    }
                    else {
                        return true;
                    }
                }
            };
            //Add the new validator to the page validators array
            Page_Validators.push(Requiredvalidator);
        }
    }

    function SetFieldAsNonRequired(fieldName) {

        if (typeof (Page_Validators) == 'undefined') return;

        if ($("#" + fieldName) != undefined && $("#" + fieldName + "_label") != undefined) {
            $("#" + fieldName).removeAttr('required');
            $("#" + fieldName).closest(".control").prev().removeClass("required");

            //Remove from page validators
            for (var i = Page_Validators.length - 1; i >= 0; i--) {
                if (Page_Validators[i].id == (fieldName + "Validator")) {
                    Page_Validators.splice(i, 1);
                }
            }
        }
    }

</script>"
}
